INSERT INTO changelog (title, body, created_at) VALUES ('Діагностика реклами: де губляться ліди', 'У Meta Ads клієнта на Огляді новий блок «Діагностика». Без кнопки — швидка оцінка правилами по кроках: крутиться (покази, відхилені) → чіпляє (CTR) → клік → заявка → навчання і зміни → куди йдуть гроші без лідів. Кнопка «Розібрати рекламу» — Джері розбирає по фактах (оголошення 7 днів проти попередніх, нові креативи, плейсменти, частота, відхилені, заявки з форм, CRM, пульс сайту) і каже головну дірку з цифрою + 3 конкретні дії; кожну можна кинути в «Шлях» стратегії. Джері на питання «чому мало лідів» тепер спершу робить цю діагностику, без загальних порад. Журнал змін реклами тепер пишеться сам: нові оголошення і зміни бюджету — щоб видно було «до» і «після». Тумблер — Можливості → «Діагностика реклами».', datetime('now'));
